def _parse_version(version):
    """Parse a SemVer 2.0.0 string into a precedence sort key."""
    # Build metadata is ignored for precedence.
    without_build = version.split('+', 1)[0]
    if '-' in without_build:
        core, prerelease = without_build.split('-', 1)
    else:
        core, prerelease = without_build, None

    major, minor, patch = (int(part) for part in core.split('.'))

    if prerelease is None:
        # A version without a pre-release has higher precedence than any
        # pre-release of the same major.minor.patch version.
        pre_key = (1,)
    else:
        identifiers = []
        for identifier in prerelease.split('.'):
            if identifier.isdigit():
                # Numeric identifiers have lower precedence than alphanumeric
                # identifiers and compare numerically.
                identifiers.append((0, int(identifier)))
            else:
                identifiers.append((1, identifier))
        pre_key = (0, tuple(identifiers))

    return (major, minor, patch, pre_key)


def sort_versions(vs):
    """Return semantic versions sorted by SemVer precedence, lowest first.

    The sort is stable, so versions with equal precedence retain their input
    order. Build metadata is ignored for ordering.
    """
    return sorted(vs, key=_parse_version)
